    31	static __net_init int sunrpc_init_net(struct net *net)
    32	{
    33		int err;
    34		struct sunrpc_net *sn = net_generic(net, sunrpc_net_id);
    35	
    36		err = rpc_proc_init(net);
    37		if (err)
    38			goto err_proc;
    39	
    40		err = ip_map_cache_create(net);
    41		if (err)
    42			goto err_ipmap;
    43	
    44		err = unix_gid_cache_create(net);
    45		if (err)
    46			goto err_unixgid;
    47	
    48		err = rpc_pipefs_init_net(net);
    49		if (err)
    50			goto err_pipefs;
    51	
    52		INIT_LIST_HEAD(&sn->all_clients);
    53		spin_lock_init(&sn->rpc_client_lock);
    54		spin_lock_init(&sn->rpcb_clnt_lock);
    55		return 0;
    56	
    57	err_pipefs:
    58		unix_gid_cache_destroy(net);
    59	err_unixgid:
    60		ip_map_cache_destroy(net);
    61	err_ipmap:
    62		rpc_proc_exit(net);
    63	err_proc:
    64		return err;
    65	}
    66	
    67	static __net_exit void sunrpc_exit_net(struct net *net)
    68	{
    69		struct sunrpc_net *sn = net_generic(net, sunrpc_net_id);
    70	
    71		rpc_pipefs_exit_net(net);
    72		unix_gid_cache_destroy(net);
    73		ip_map_cache_destroy(net);
    74		rpc_proc_exit(net);
    75		WARN_ON_ONCE(!list_empty(&sn->all_clients));
    76	}
