    90			goto out;
    91		err = rpcauth_init_module();
    92		if (err)
    93			goto out2;
    94	
    95		cache_initialize();
    96	
    97		err = register_pernet_subsys(&sunrpc_net_ops);
    98		if (err)
    99			goto out3;
   100	
   101		err = register_rpc_pipefs();
   102		if (err)
   103			goto out4;
   104	
   105		sunrpc_debugfs_init();
   106	#if IS_ENABLED(CONFIG_SUNRPC_DEBUG)
   107		rpc_register_sysctl();
